\mathsf{ConvCert}_{P}
=
\left\{
(E_0,\ldots,E_n):
\begin{array}{l}
n\in\mathbb N,\ E_i\in\mathsf{Exp}_{P},\\
\text{每个 }i<n\text{ 满足 }
E_i\equiv_\alpha^{P}E_{i+1}\ \vee\
(E_i,E_{i+1})\in\mathsf{Step}_{P}\ \vee\
(E_{i+1},E_i)\in\mathsf{Step}_{P}
\end{array}
\right\}.

\mathsf{Ctx}_{P}
=\{(x_i:A_i)_{i<n}:n\in\mathbb N,\ \forall i<n\ (x_i\in\mathsf{Var}_{P}\land A_i\in\mathsf{Exp}_{P}),\
\forall i,j<n\ (i\ne j\Rightarrow x_i\ne x_j)\}.
